<script setup lang="ts">
import { RefreshRight, VideoPlay, WarningFilled } from '@element-plus/icons-vue';
import { computed, inject, onMounted, reactive, ref } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import AdminShell from '../layouts/AdminShell.vue';
import { reviewStatusLabel, riskLabel, type ReviewDecision, type ReviewQuery, type ReviewRepository, type ReviewRiskLevel, type ReviewTask, type ReviewTaskStatus } from '../features/review/model';
import { ReviewRepositoryError, reviewRepositoryKey } from '../features/review/repository';

const injectedRepository = inject<ReviewRepository>(reviewRepositoryKey);
if (!injectedRepository) throw new Error('Review repository is not configured');
const repository: ReviewRepository = injectedRepository;
const tasks = ref<ReviewTask[]>([]); const total = ref(0); const loading = ref(true); const refreshing = ref(false); const error = ref<{ message: string; traceId?: string }>(); const requestId = ref(0);
const query = reactive<ReviewQuery>({ page: 1, pageSize: 20, keyword: '', riskLevel: undefined, authorId: undefined });
const selected = ref<ReviewTask>(); const drawerOpen = ref(false); const decisionOpen = ref(false); const decision = ref<Exclude<ReviewDecision, 'APPROVE'>>('REJECT'); const reason = ref(''); const actionLoading = ref('');
const statuses: ReviewTaskStatus[] = ['PENDING', 'CLAIMED', 'APPROVED', 'REJECTED', 'REVISION_REQUIRED']; const risks: ReviewRiskLevel[] = ['LOW', 'MEDIUM', 'HIGH'];
const canDecide = computed(() => selected.value?.status === 'CLAIMED' && Boolean(selected.value));
function time(value: string) { return new Intl.DateTimeFormat('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false, timeZone: 'Asia/Shanghai' }).format(new Date(value)); }
function riskType(value: ReviewRiskLevel) { return value === 'HIGH' ? 'danger' : value === 'MEDIUM' ? 'warning' : 'success'; }
async function load() { const id = ++requestId.value; const initial = !tasks.value.length; loading.value = initial; refreshing.value = !initial; error.value = undefined; try { const result = await repository.list(query); if (id !== requestId.value) return; tasks.value = result.items; total.value = result.total; } catch (caught) { if (id === requestId.value) { const typed = caught instanceof ReviewRepositoryError ? caught : undefined; error.value = { message: typed?.message ?? '审核队列加载失败', traceId: typed?.traceId }; } } finally { if (id === requestId.value) { loading.value = false; refreshing.value = false; } } }
function search() { query.page = 1; void load(); } function reset() { Object.assign(query, { page: 1, keyword: '', riskLevel: undefined, authorId: undefined }); void load(); }
async function openTask(task: ReviewTask) { drawerOpen.value = true; selected.value = undefined; try { selected.value = await repository.get(task.videoId); } catch (caught) { ElMessage.error(caught instanceof Error ? caught.message : '详情加载失败'); } }
async function refreshSelected() { if (selected.value) selected.value = await repository.get(selected.value.videoId); }
async function claim(task: ReviewTask) { actionLoading.value = `claim-${task.videoId}`; try { await repository.claim(task.videoId, task.version); await load(); if (drawerOpen.value) await refreshSelected(); else await openTask(task); ElMessage.success('已领取审核任务'); } catch (caught) { const typed = caught instanceof ReviewRepositoryError ? caught : undefined; ElMessage.error(typed?.code === 'TASK_ALREADY_CLAIMED' ? '任务已被其他审核员领取，已刷新队列' : typed?.message ?? '领取失败'); await load(); if (drawerOpen.value) await refreshSelected(); } finally { actionLoading.value = ''; } }
async function approve() { if (!selected.value) return; try { await ElMessageBox.confirm(`确认通过《${selected.value.title}》？通过后将立即发布。`, '确认通过审核', { type: 'warning', confirmButtonText: '确认通过' }); actionLoading.value = `approve-${selected.value.videoId}`; selected.value = await repository.decide(selected.value.videoId, { decision: 'APPROVE', currentVersion: selected.value.version }); await load(); ElMessage.success('审核已通过，视频将立即发布'); } catch (caught) { if (caught !== 'cancel' && caught !== 'close') await handleActionError(caught); } finally { actionLoading.value = ''; } }
function openDecision(next: Exclude<ReviewDecision, 'APPROVE'>) { decision.value = next; reason.value = ''; decisionOpen.value = true; }
async function submitDecision() { if (!selected.value || !reason.value.trim()) return; actionLoading.value = `decision-${selected.value.videoId}`; try { selected.value = await repository.decide(selected.value.videoId, { decision: decision.value, reason: reason.value.trim(), currentVersion: selected.value.version }); decisionOpen.value = false; await load(); ElMessage.success(decision.value === 'REJECT' ? '已驳回视频' : '已要求作者修改'); } catch (caught) { await handleActionError(caught); } finally { actionLoading.value = ''; } }
async function handleActionError(caught: unknown) { const typed = caught instanceof ReviewRepositoryError ? caught : undefined; if (typed?.code === 'VERSION_CONFLICT' || typed?.code === 'TASK_NOT_CLAIMED_BY_CURRENT_REVIEWER' || typed?.code === 'TASK_ALREADY_CLAIMED') { ElMessage.error('任务状态已变化，已重新加载最新信息'); await load(); await refreshSelected(); return; } if (typed?.code === 'TASK_NOT_FOUND') { drawerOpen.value = false; await load(); } ElMessage.error(typed?.message ?? '审核操作失败'); }
onMounted(() => { void load(); });
</script>

<template>
  <AdminShell page-title="审核管理" page-subtitle="处理待审核视频、风险提示与审核记录"><section class="review-page"><header class="page-header"><div><h2>审核管理</h2><p>领取并处理待审核视频内容</p></div><el-button :icon="RefreshRight" :loading="refreshing" @click="load">刷新</el-button></header>
    <div class="filters"><el-input v-model="query.keyword" placeholder="标题、视频 ID 或作者" clearable @keyup.enter="search" /><el-select v-model="query.riskLevel" placeholder="全部风险" clearable><el-option v-for="risk in risks" :key="risk" :value="risk" :label="riskLabel[risk]" /></el-select><el-button type="primary" @click="search">查询</el-button><el-button @click="reset">重置</el-button></div>
    <section v-if="error && !tasks.length" class="error-state"><el-icon><WarningFilled /></el-icon><p>{{ error.message }}</p><small v-if="error.traceId">诊断编号：{{ error.traceId }}</small><el-button @click="load">重试</el-button></section>
    <section v-else class="table-shell" v-loading="loading || refreshing"><div v-if="error" class="inline-error">{{ error.message }} <button type="button" @click="load">重试</button></div><el-table :data="tasks"><el-table-column label="视频" min-width="240"><template #default="{ row }"><button type="button" class="title-link" @click="openTask(row)">{{ row.title }}</button><small>ID {{ row.videoId }} · {{ row.author }}</small></template></el-table-column><el-table-column label="分类/标签" min-width="150"><template #default="{ row }"><span>{{ row.category }}</span><small>{{ row.tags.join(' · ') || '--' }}</small></template></el-table-column><el-table-column label="风险" width="125"><template #default="{ row }"><el-tag :type="riskType(row.riskLevel)" effect="plain">{{ riskLabel[row.riskLevel as ReviewRiskLevel] }}</el-tag><small v-if="row.findings.length">{{ row.findings[0].source }}</small></template></el-table-column><el-table-column label="提交时间" width="145"><template #default="{ row }">{{ time(row.submittedAt) }}</template></el-table-column><el-table-column label="领取状态" width="145"><template #default="{ row }"><span v-if="row.status === 'CLAIMED'">{{ row.claimedBy }}</span><span v-else>{{ reviewStatusLabel[row.status as ReviewTaskStatus] }}</span></template></el-table-column><el-table-column label="操作" width="175" fixed="right"><template #default="{ row }"><el-button link :icon="VideoPlay" @click="openTask(row)">{{ row.status === 'CLAIMED' ? '继续审核' : '查看' }}</el-button><el-button v-if="row.status === 'PENDING'" link type="primary" :loading="actionLoading === `claim-${row.videoId}`" @click="claim(row)">领取审核</el-button></template></el-table-column></el-table><el-pagination v-if="total" v-model:current-page="query.page" :page-size="query.pageSize" :total="total" layout="total, prev, pager, next" @current-change="load" /></section>
  </section>
  <el-drawer v-model="drawerOpen" title="视频审核" size="540px"><div v-if="selected" class="detail"><div class="preview">预览暂不可用</div><div class="detail-head"><div><h3>{{ selected.title }}</h3><p>{{ selected.author }} · {{ selected.category }}</p></div><el-tag :type="riskType(selected.riskLevel)">{{ riskLabel[selected.riskLevel] }}</el-tag></div><p>{{ selected.description }}</p><section><h4>机器风险预检</h4><ul v-if="selected.findings.length" class="findings"><li v-for="finding in selected.findings" :key="finding.description"><el-tag :type="riskType(finding.level)" size="small">{{ riskLabel[finding.level] }}</el-tag><b>{{ finding.source }} · {{ finding.score }} 分</b><span>{{ finding.description }}</span></li></ul><p v-else class="muted">未发现机器预检风险。</p></section><section><h4>审核记录</h4><ol class="history"><li v-for="entry in selected.history" :key="`${entry.action}-${entry.createdAt}`"><b>{{ entry.operator }} · {{ entry.action }}</b><time>{{ time(entry.createdAt) }}</time><p v-if="entry.reason">{{ entry.reason }}</p></li></ol></section><div class="claim-info">{{ selected.claimedBy ? `当前由 ${selected.claimedBy} 领取` : '当前任务尚未领取' }}</div><footer class="drawer-actions"><el-button v-if="selected.status === 'PENDING'" type="primary" :loading="actionLoading === `claim-${selected.videoId}`" @click="claim(selected)">领取审核</el-button><template v-else-if="canDecide"><el-button type="success" :loading="actionLoading === `approve-${selected.videoId}`" @click="approve">通过并发布</el-button><el-button type="danger" @click="openDecision('REJECT')">驳回</el-button><el-button @click="openDecision('REQUEST_REVISION')">要求修改</el-button></template></footer></div><el-skeleton v-else :rows="9" animated /></el-drawer>
  <el-dialog v-model="decisionOpen" :title="decision === 'REJECT' ? '驳回视频' : '要求修改'" width="460px"><p>{{ decision === 'REJECT' ? '请填写驳回原因，作者将据此调整内容。' : '请明确说明需要修改的内容。' }}</p><el-input v-model="reason" type="textarea" :rows="4" maxlength="300" show-word-limit placeholder="请输入审核原因" /><template #footer><el-button @click="decisionOpen = false">取消</el-button><el-button type="danger" :disabled="!reason.trim()" :loading="actionLoading.startsWith('decision-')" @click="submitDecision">确认提交</el-button></template></el-dialog>
  </AdminShell>
</template>

<style scoped>
.review-page { display: grid; gap: 16px; }.page-header { display: flex; align-items: end; justify-content: space-between; }.page-header h2 { margin: 0; font-size: 20px; }.page-header p { margin: 6px 0 0; color: var(--yl-text-muted); font-size: 12px; }.filters { display: flex; align-items: center; gap: 10px; padding: 14px; background: var(--yl-surface); border: 1px solid var(--yl-border); border-radius: 8px; }.filters .el-input { width: 250px; }.filters .el-select { width: 130px; }.table-shell { overflow: hidden; min-height: 300px; background: var(--yl-surface); border: 1px solid var(--yl-border); border-radius: 8px; }.title-link { max-width: 100%; padding: 0; overflow: hidden; color: var(--yl-text); background: transparent; border: 0; font-weight: 600; text-align: left; text-overflow: ellipsis; white-space: nowrap; cursor: pointer; }.title-link:hover { color: var(--yl-indigo); }.el-table small { display: block; margin-top: 3px; color: var(--yl-text-muted); font-size: 10px; }.el-pagination { justify-content: flex-end; padding: 14px 18px; }.error-state { display: grid; justify-items: center; gap: 10px; padding: 70px; background: var(--yl-surface); border: 1px solid var(--yl-border); border-radius: 8px; }.error-state .el-icon { color: var(--yl-coral); font-size: 28px; }.error-state p { margin: 0; }.error-state small { color: var(--yl-text-muted); }.inline-error { padding: 9px 14px; color: #9f3b42; background: #fff6f6; font-size: 12px; }.inline-error button { margin-left: 8px; color: inherit; background: none; border: 0; text-decoration: underline; cursor: pointer; }.detail { display: grid; gap: 18px; }.preview { display: grid; min-height: 190px; place-items: center; color: var(--yl-text-muted); background: #f2f4f8; border-radius: 6px; }.detail-head { display: flex; justify-content: space-between; gap: 15px; }.detail h3, .detail p, .detail h4 { margin: 0; }.detail-head p, .muted { margin-top: 5px !important; color: var(--yl-text-muted); font-size: 12px; }.detail section { display: grid; gap: 10px; }.findings, .history { display: grid; gap: 9px; margin: 0; padding: 0; list-style: none; }.findings li { display: grid; gap: 5px; padding: 10px; background: #fff8f5; border: 1px solid #f8e1d8; border-radius: 6px; font-size: 12px; }.findings b { color: var(--yl-text-secondary); }.history { border-left: 2px solid var(--yl-border); padding-left: 14px; }.history li { position: relative; }.history li::before { position: absolute; left: -19px; top: 3px; width: 8px; height: 8px; content: ''; background: var(--yl-indigo); border-radius: 50%; }.history b, .history time { display: block; font-size: 12px; }.history time { margin-top: 3px; color: var(--yl-text-muted); }.history p { margin-top: 5px; color: var(--yl-text-secondary); font-size: 12px; }.claim-info { padding: 10px; color: var(--yl-text-secondary); background: var(--yl-surface-subtle); border-radius: 5px; font-size: 12px; }.drawer-actions { display: flex; gap: 10px; padding-top: 4px; }
</style>
